import express from 'express';
import { createStore } from 'zustand/vanilla';
import { patientAuth } from '../middleware/patientAuth.js';
import { MedicalRecord } from '../models/medicalRecord.js';

const app = express();

const createClinicalStore = () => createStore((set) => ({
  patientRecord: null,
  setRecord: (record) => set({ patientRecord: record })
}));

app.get('/ssr/patient/records/:recordId', patientAuth, async (req, res) => {
  const { recordId } = req.params;

  // Constrain lookup strictly to the authenticated patient's records
  const record = await MedicalRecord.findOne({
    where: { id: recordId, patientId: req.user.patientId }
  });
  if (!record) return res.status(404).send('Record not found or access denied');

  // Request-isolated Zustand store instantiation
  const requestStore = createClinicalStore();
  requestStore.getState().setRecord({
    id: record.id,
    patientName: record.patientFullName,
    diagnoses: record.clinicalDiagnoses,
    labSummaries: record.labSummaries
  });

  const state = requestStore.getState();
  res.send(`
    <html>
      <script>window.__SSR_CLINICAL__ = ${JSON.stringify(state)};</script>
      <body><h1>Patient Portal: ${state.patientRecord.patientName}</h1></body>
    </html>
  `);
});

export default app;
